const { files, directory, urls, chunkStrategy, chunkSize, chunkOverlap, extractImages, extractTables, metadata } = $json.body;

let filePaths = [];
let urlList = [];

if (files && Array.isArray(files)) filePaths = files;
if (urls && Array.isArray(urls)) urlList = urls;

if (directory) {
  const fs = require('fs');
  const path = require('path');
  function walkDir(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) walkDir(fullPath);
      else if (/\.(md|txt|pdf|js|ts|py|json|yaml|yml|html|css|mdx|csv|docx|pptx|xlsx)$/i.test(entry.name)) {
        filePaths.push(fullPath);
      }
    }
  }
  walkDir(directory);
}

const strategy = chunkStrategy || 'recursive';
const size = chunkSize || 1000;
const overlap = chunkOverlap || 200;

return filePaths.map(fp => ({ json: { filePath: fp, strategy, size, overlap, extractImages: !!extractImages, extractTables: !!extractTables, metadata: metadata || {} } }))
  .concat(urlList.map(u => ({ json: { url: u, strategy, size, overlap, metadata: metadata || {} } })));

const fs = require('fs');
const path = require('path');
const { filePath, url, strategy, size, overlap, extractImages, extractTables, metadata } = $json;

let content = '';
let images = [];
let tables = [];
let docMetadata = { ...metadata };

if (filePath) {
  const ext = path.extname(filePath).toLowerCase();
  docMetadata.source = filePath;
  docMetadata.filename = path.basename(filePath);

  try {
    if (ext === '.pdf') {
      const pdf = require('pdf-parse');
      const buffer = fs.readFileSync(filePath);
      const data = await pdf(buffer);
      content = data.text;
      docMetadata.pageCount = data.numpages;

      if (extractImages) {
        const pdf2pic = require('pdf2pic');
        // Extract images logic here
      }
    } else if (ext === '.docx') {
      const mammoth = require('mammoth');
      const buffer = fs.readFileSync(filePath);
      const result = await mammoth.extractRawText({ buffer });
      content = result.value;
    } else if (ext === '.csv') {
      const csv = require('csv-parse/sync');
      const text = fs.readFileSync(filePath, 'utf-8');
      const records = csv.parse(text, { columns: true });
      content = JSON.stringify(records, null, 2);
      docMetadata.rowCount = records.length;
    } else {
      content = fs.readFileSync(filePath, 'utf-8');
    }
  } catch (e) {
    return [{ json: { filePath, url, error: e.message, content: '', images, tables, metadata: docMetadata } }];
  }
} else if (url) {
  const https = require('https');
  const http = require('http');
  const client = url.startsWith('https') ? https : http;

  try {
    const response = await new Promise((resolve, reject) => {
      client.get(url, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve({ statusCode: res.statusCode, data }));
      }).on('error', reject);
    });

    if (response.statusCode === 200) {
      const cheerio = require('cheerio');
      const $ = cheerio.load(response.data);
      $('script, style, nav, footer, aside').remove();
      content = $('body').text().replace(/\s+/g, ' ').trim();
      docMetadata.source = url;
      docMetadata.title = $('title').text();
    } else {
      return [{ json: { url, error: `HTTP ${response.statusCode}`, content: '', metadata: docMetadata } }];
    }
  } catch (e) {
    return [{ json: { url, error: e.message, content: '', metadata: docMetadata } }];
  }
}

if (!content || content.trim().length === 0) {
  return [{ json: { filePath, url, error: 'No content extracted', content: '', metadata: docMetadata } }];
}

return [{ json: { filePath, url, content, images, tables, metadata: docMetadata, strategy, size, overlap } }];

const { content, strategy, size, overlap, metadata, filePath, url } = $json;

const chunkers = {
  recursive: (text) => {
    const separators = ['\n\n', '\n', '. ', '? ', '! ', '; ', ', ', ' ', ''];
    const chunks = [];
    let start = 0;

    function splitText(text, separatorIndex = 0) {
      if (separatorIndex >= separators.length) return [text];
      const separator = separators[separatorIndex];
      const parts = text.split(separator);

      if (parts.length === 1) return splitText(text, separatorIndex + 1);

      let result = [];
      let current = '';

      for (const part of parts) {
        const candidate = current + (current ? separator : '') + part;
        if (candidate.length > size && current) {
          result.push(current);
          current = part;
        } else {
          current = candidate;
        }
      }
      if (current) result.push(current);

      return result.flatMap(chunk => chunk.length > size ? splitText(chunk, separatorIndex + 1) : [chunk]);
    }

    const rawChunks = splitText(text);

    for (let i = 0; i < rawChunks.length; i++) {
      let chunk = rawChunks[i].trim();
      if (!chunk) continue;

      if (i > 0 && overlap > 0) {
        const prevEnd = rawChunks[i-1].trim();
        const overlapText = prevEnd.slice(-overlap);
        chunk = overlapText + ' ' + chunk;
      }

      chunks.push({
        text: chunk,
        index: i,
        startChar: start,
        endChar: start + chunk.length,
        metadata: { ...metadata, chunkIndex: i, chunkStrategy: strategy }
      });
      start += chunk.length;
    }
    return chunks;
  },

  semantic: (text) => {
    const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];
    const chunks = [];
    let currentChunk = '';
    let start = 0;

    for (let i = 0; i < sentences.length; i++) {
      const sentence = sentences[i].trim();
      if ((currentChunk + ' ' + sentence).length > size && currentChunk) {
        chunks.push({
          text: currentChunk.trim(),
          index: chunks.length,
          startChar: start,
          endChar: start + currentChunk.length,
          metadata: { ...metadata, chunkIndex: chunks.length, chunkStrategy: strategy }
        });
        start += currentChunk.length;
        currentChunk = sentence;
      } else {
        currentChunk += (currentChunk ? ' ' : '') + sentence;
      }
    }
    if (currentChunk) {
      chunks.push({
        text: currentChunk.trim(),
        index: chunks.length,
        startChar: start,
        endChar: start + currentChunk.length,
        metadata: { ...metadata, chunkIndex: chunks.length, chunkStrategy: strategy }
      });
    }
    return chunks;
  },

  fixed: (text) => {
    const chunks = [];
    let start = 0;
    while (start < text.length) {
      const end = Math.min(start + size, text.length);
      let chunk = text.slice(start, end);
      if (end < text.length) {
        const lastSpace = chunk.lastIndexOf(' ');
        if (lastSpace > size * 0.5) {
          chunk = chunk.slice(0, lastSpace);
        }
      }
      chunks.push({
        text: chunk.trim(),
        index: chunks.length,
        startChar: start,
        endChar: end,
        metadata: { ...metadata, chunkIndex: chunks.length, chunkStrategy: strategy }
      });
      start = end - overlap;
      if (start >= text.length) break;
    }
    return chunks;
  }
};

const chunker = chunkers[strategy] || chunkers.recursive;
const chunks = chunker(content);

return chunks.map(c => ({ json: { ...c, filePath, url, docMetadata: metadata } }));

const { text, metadata } = $json;
const BM25 = require('bm25');

if (!global.bm25Corpus) global.bm25Corpus = [];
if (!global.bm25Index) {
  global.bm25Index = new BM25();
}

const docId = `${metadata.filePath || metadata.url}_${metadata.chunkIndex}_${Date.now()}`;
global.bm25Corpus.push({ id: docId, text });
global.bm25Index.addDocument(docId, text);

return [{ json: { ...$json, bm25Id: docId, sparseVector: 'bm25_handled_separately' } }];

const { data, text, metadata, filePath, url, bm25Id } = $json;

const denseVector = data[0].embedding;

const point = {
  id: bm25Id || `${filePath || url}_${metadata.chunkIndex}_${Date.now()}`, 
  vector: denseVector,
  payload: {
    text,
    filePath,
    url,
    metadata: { ...metadata, denseModel: 'nvidia/nv-embedqa-e5-v5' }
  }
};

return [{ json: point }];

const { query, topK, hybridWeight, rerank, rerankModel, filters, searchMode } = $json.body;

const weight = hybridWeight ?? 0.5;
const k = topK || 10;
const doRerank = rerank !== false;
const model = rerankModel || 'nvidia/nemotron-3-ultra-550b-a55b';
const mode = searchMode || 'hybrid';

return [{ json: { query, topK: k, hybridWeight: weight, doRerank, rerankModel: model, filters, searchMode: mode } }];

const { query, topK, hybridWeight, filters } = $json;
const denseVector = $json.data[0].embedding;

if (!global.bm25Index || !global.bm25Corpus) {
  return [{ json: { query, denseVector, bm25Results: [], topK, hybridWeight, filters } }];
}

const bm25Results = global.bm25Index.getTopN(query, topK * 2);

return [{ json: { query, denseVector, bm25Results, topK, hybridWeight, filters } }];

const { denseResults, bm25Results, topK, hybridWeight, query, doRerank, rerankModel } = $json;

const dense = denseResults.data?.result || [];
const sparse = bm25Results || [];

const denseMap = new Map();
dense.forEach((r, i) => {
  denseMap.set(r.id, { score: r.score, rank: i, payload: r.payload });
});

const sparseMap = new Map();
sparse.forEach((r, i) => {
  sparseMap.set(r.id, { score: r.score, rank: i });
});

const allIds = new Set([...denseMap.keys(), ...sparseMap.keys()]);
const fused = [];

for (const id of allIds) {
  const d = denseMap.get(id);
  const s = sparseMap.get(id);

  const denseScore = d ? 1 - (d.rank / (dense.length || 1)) : 0;
  const sparseScore = s ? 1 - (s.rank / (sparse.length || 1)) : 0;

  const fusedScore = hybridWeight * denseScore + (1 - hybridWeight) * sparseScore;

  fused.push({
    id,
    score: fusedScore,
    denseScore,
    sparseScore,
    payload: d?.payload
  });
}

fused.sort((a, b) => b.score - a.score);
const topResults = fused.slice(0, topK);

if (doRerank && topResults.length > 1) {
  return [{ json: { query, candidates: topResults, rerankModel, topK } }];
}

return [{ json: { query, results: topResults, reranked: false } }];

const { query, candidates, rerankModel, topK } = $json;

const pairs = candidates.map(c => [query, c.payload?.text || '']);

const https = require('https');
const data = JSON.stringify({
  model: rerankModel || 'nvidia/nemotron-3-ultra-550b-a55b',
  messages: pairs.map(p => [
    { role: 'system', content: 'Score the relevance of the document to the query on a scale of 0-1. Return only a number.' },
    { role: 'user', content: `Query: ${p[0]}\nDocument: ${p[1]}` }
  ])
});

const options = {
  hostname: 'integrate.api.nvidia.com',
  path: '/v1/chat/completions',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.NVIDIA_API_KEY || process.env.HUGGINGFACE_API_KEY}`
  }
};

return new Promise((resolve) => {
  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      try {
        const result = JSON.parse(data);
        const scores = result.choices?.map(c => parseFloat(c.message?.content || '0')) || [];
        candidates.forEach((c, i) => {
          c.rerankScore = scores[i] || 0;
        });
        candidates.sort((a, b) => (b.rerankScore || 0) - (a.rerankScore || 0));
        resolve([{ json: { query, results: candidates.slice(0, topK), reranked: true } }]);
      } catch (e) {
        resolve([{ json: { query, results: candidates.slice(0, topK), reranked: false, error: e.message } }]);
      }
    });
  });
  req.on('error', (e) => resolve([{ json: { query, results: candidates.slice(0, topK), reranked: false, error: e.message } }]));
  req.write(data);
  req.end();
});

const { query, results, reranked } = $json;

const context = results.map((r, i) => `\n[Doc ${i+1} | Score: ${(r.rerankScore || r.score).toFixed(4)} | Source: ${r.payload?.filePath || r.payload?.url || 'unknown'}]\n${r.payload?.text || ''}`).join('\n---\n');

const systemPrompt = `You are an expert research assistant. Answer the question using ONLY the provided context.

Guidelines:
1. Cite sources using [Doc X] format
2. If context is insufficient, say "I don't have enough information to answer"
3. Synthesize across multiple sources when possible
4. Be precise and concise
5. Include confidence level (High/Medium/Low)

Context:
${context}`;

return [{ json: { systemPrompt, query, context, results, model: 'nvidia/nemotron-3-ultra-550b-a55b', temperature: 0.1 } }];

const answer = $json.choices[0].message.content;
const { query, results } = $json;

return [{ json: {
  success: true,
  query,
  answer,
  sources: results.map(r => ({
    id: r.id,
    score: r.rerankScore || r.score,
    source: r.payload?.filePath || r.payload?.url,
    preview: r.payload?.text?.substring(0, 300)
  })),
  usage: $json.usage
} }];

const response = $json.choices[0].message.content;
const { messages, maxSteps, tools, step = 1 } = $json.body;

const actionMatch = response.match(/Action:\s*(\w+)\s*\nAction Input:\s*(\{[\s\S]*?\})/);
const finalMatch = response.match(/Final Answer:\s*([\s\S]*)/);

if (finalMatch) {
  return [{ json: { done: true, answer: finalMatch[1].trim(), messages: [...messages, { role: 'assistant', content: response }] } }];
}

if (actionMatch && step < maxSteps) {
  const [, toolName, toolInput] = actionMatch;
  let params = {};
  try { params = JSON.parse(toolInput); } catch { params = {}; }

  let observation = '';

  if (toolName === 'search_hybrid') {
    // Call hybrid search internally
    observation = await $execute('hybrid_search', params);
  } else if (toolName === 'fetch_document') {
    observation = await $execute('fetch_doc', params);
  } else {
    observation = `Unknown tool: ${toolName}`;
  }

  const newMessages = [
    ...messages,
    { role: 'assistant', content: response },
    { role: 'user', content: `Observation: ${observation}` }
  ];

  return [{ json: {
    done: false,
    messages: newMessages,
    step: step + 1,
    maxSteps,
    tools,
    model: $json.body.model,
    temperature: 0.1
  } }];
}

return [{ json: { done: true, answer: response, messages } }];

const { testQueries, groundTruth, metrics } = $json.body;

const evalPrompt = `You are an RAG evaluator. For each query, evaluate the answer quality.

Test Cases:
${testCases.map((t, i) => `${i+1}. Query: ${t.query}\nExpected: ${t.expected}\nActual: ${t.actual}`).join('\n\n')}

Metrics to score (1-5):
- Faithfulness: Does answer match retrieved context?
- Relevance: Does answer address the query?
- Completeness: Are all aspects covered?
- Conciseness: Is answer appropriately brief?

Output JSON: {"results": [{"query": "", "scores": {"faithfulness": 0, "relevance": 0, "completeness": 0, "conciseness": 0}, "reasoning": ""}]}`;

return [{ json: { systemPrompt: 'You are an expert evaluator. Be strict but fair.', userPrompt: evalPrompt, model: 'nvidia/nemotron-3-ultra-550b-a55b', temperature: 0 } }];

const evalResult = $json.choices[0].message.content;
try {
  const parsed = JSON.parse(evalResult);
  const avgScores = {};
  if (parsed.results?.length) {
    const keys = Object.keys(parsed.results[0].scores || {});
    keys.forEach(k => {
      avgScores[k] = parsed.results.reduce((sum, r) => sum + (r.scores?.[k] || 0), 0) / parsed.results.length;
    });
  }
  return [{ json: { success: true, evaluation: parsed, averageScores: avgScores, usage: $json.usage } }];
} catch {
  return [{ json: { success: true, evaluation: evalResult, usage: $json.usage } }];
}
